# R3-I SigV4 vector court (v26.11.6 repositioning wave) — smalt side.
#
# Oracle: verification/sigv4_vectors.json, generated by a one-shot
# :aws_signature (aws_signature ~> 0.4) script in this toolchain against
# fixed-date vectors (x-amz-date 20260101T000000Z, synthetic creds
# AKIDVECTOR / vectorSecret123). Pinned creds via Application.put_env on the
# real Smalt.Egress.KinesisRoutes verify_sigv4 path (re-sign-and-compare).
#
# FALSIFIER (non-vacuity, per fleet law): flipping one byte of the
# get_query_edges expected_signature in the JSON ('9'->'8') was executed
# during this wave and flipped BOTH courts:
#   arcus: --- FAIL: TestSignatureVectors/get_query_edges: got error SignatureDoesNotMatch, want nil
#   smalt: ** (ExUnit.AssertionError) "signature mismatch" (expected :ok)
# Both courts read the same canonical bytes; one vector mutation flips both.
#
# DIVERGENCE LEDGER (tested against ACTUAL smalt behavior, never assumed):
# - rejection/dropped_signed_header: smalt signed_headers_of/2 DROPS absent
#   headers from the re-sign (arcus emits them empty-valued and rejects).
#   Actual smalt behavior under this vector: ACCEPTED (re-sign matches the
#   reduced set) — recorded in docs/jira/v26.11.6/KNOWN_DIVERGENCES.md as
#   KD-SIGV4-1 (explicit, never silent).
# - rejection/unsorted_signed_headers: smalt re-signs over the client's own
#   (deduped) order, so it accepts an unsorted list where arcus rejects with
#   ErrSignedHeadersUnsorted — KD-SIGV4-2.
defmodule Smalt.Test.SigV4.SigV4VectorsTest do
  use ExUnit.Case, async: false

  import Plug.Test

  @vectors_path "/Users/sac/smalt/verification/sigv4_vectors.json"
  @akid "AKIDVECTOR"
  @secret "vectorSecret123"
  @region "us-east-1"

  setup do
    prev = Application.get_env(:smalt, :kinesis)
    Application.put_env(:smalt, :kinesis, %{
      access_key_id: @akid,
      secret_access_key: @secret,
      region: @region
    })

    table_existed = :ets.info(:smalt_eh_partitions) != :undefined

    if table_existed do
      :ok
    else
      :ets.new(:smalt_eh_partitions, [:named_table, :public, :set])
    end

    on_exit(fn ->
      if prev do
        Application.put_env(:smalt, :kinesis, prev)
      else
        Application.delete_env(:smalt, :kinesis)
      end

      if table_existed do
        :ok
      else
        :ets.delete(:smalt_eh_partitions)
      end
    end)

    :ok
  end

  defp load_vectors do
    @vectors_path |> File.read!() |> Jason.decode!()
  end

  # Build a Plug conn fixture carrying the vector's wire shape through the
  # real KinesisRoutes plug pipeline (kinesis_arm -> verify_sigv4).
  defp wire_conn(%{"method" => "POST", "path" => path, "raw_query" => raw_query} = vec) do
    headers =
      vec["headers"]
      |> Map.delete("Host")
      |> Enum.map(fn {k, v} -> {String.downcase(k), v} end)

    conn(:post, path <> "?" <> raw_query, vec["body"])
    |> Plug.Conn.put_req_header("host", "localhost")
    |> Plug.Conn.put_req_header("authorization", vec["authorization"])
    |> then(fn c -> Enum.reduce(headers, c, fn {k, v}, c -> Plug.Conn.put_req_header(c, k, v) end) end)
    |> Plug.Conn.put_req_header("x-amz-target", "R3IProbeAction")
  end

  defp wire_conn(%{"method" => "GET"} = vec) do
    headers =
      vec["headers"]
      |> Map.delete("Host")
      |> Enum.map(fn {k, v} -> {String.downcase(k), v} end)

    conn(:get, vec["path"] <> "?" <> vec["raw_query"], nil)
    |> Plug.Conn.put_req_header("host", "localhost")
    |> Plug.Conn.put_req_header("authorization", vec["authorization"])
    |> then(fn c -> Enum.reduce(headers, c, fn {k, v}, c -> Plug.Conn.put_req_header(c, k, v) end) end)
    |> Plug.Conn.put_req_header("x-amz-target", "R3IProbeAction")
  end

  defp call_plug(conn) do
    Smalt.Egress.KinesisRoutes.call(conn, [])
  end

  # The vector requests target this probe action; dispatch_target answers
  # 400 InvalidActionException AFTER auth passes, which is the observable
  # "verification passed" final state (Chicago: assert on real outcome).
  test "signature_vectors pass the real verify_sigv4 path" do
    doc = load_vectors()

    Enum.each(doc["signature_vectors"], fn vec ->
      conn = vec |> wire_conn() |> call_plug()

      assert conn.status == 400,
             "#{vec["name"]}: expected auth to pass (400 InvalidActionException after verify), got #{conn.status}"

      assert Jason.decode!(conn.resp_body)["code"] == "InvalidActionException"
    end)
  end

  test "canonical_query_vectors match the committed canonical bytes" do
    doc = load_vectors()

    Enum.each(doc["canonical_query_vectors"], fn vec ->
      # The encoder law is asserted via the aws_signature-consistent unreserved
      # set: re-encode the decoded raw query and compare to expected_canonical.
      decoded = URI.decode_query(vec["raw_query"])
      got = encode_query(decoded)
      assert got == vec["expected_canonical"], "#{vec["name"]}: #{got} != #{vec["expected_canonical"]}"
    end)
  end

  test "rejection_vectors through the real path (divergences recorded, not assumed)" do
    doc = load_vectors()

    Enum.each(doc["rejection_vectors"], fn vec ->
      conn = vec |> wire_conn() |> call_plug()

      case {vec["kind"], conn.status} do
        # Divergences (KD-SIGV4-1/2): smalt accepts where arcus rejects.
        {"drop_header", 400} ->
          assert Jason.decode!(conn.resp_body)["code"] == "InvalidActionException"

        {"signed_headers_order", 400} ->
          assert Jason.decode!(conn.resp_body)["code"] == "InvalidActionException"

        # Lawful rejections through the real path.
        {kind, 403} ->
          assert Jason.decode!(conn.resp_body)["code"] == "InvalidSignatureException",
                 "#{vec["name"]} (#{kind}): expected typed 403, got #{conn.status} #{conn.resp_body}"

        {kind, other} ->
          flunk("#{vec["name"]} (#{kind}): unexpected status #{other}")
      end
    end
  end

  # RFC3986 strict URI encode matching the arcus awsURIEncode law and the
  # aws_signature oracle: unreserved set passes, space -> %20, else %XX upper.
  @unreserved MapSet.new(Enum.to_list(?a..?z) ++ Enum.to_list(?A..?Z) ++ Enum.to_list(?0..?9) ++ [?-, ?., ?_, ?~])

  defp uri_encode(bin), do: do_encode(bin, "")

  defp do_encode(<<c, rest::binary>>, acc) do
    piece =
      cond do
        c == ?\s -> "%20"
        MapSet.member?(@unreserved, c) -> <<c>>
        true -> "%" <> String.upcase(Integer.to_string(c, 16))
      end

    do_encode(rest, acc <> piece)
  end

  defp do_encode(<<>>, acc), do: acc

  defp encode_query(decoded) do
    decoded
    |> Enum.map(fn {k, v} -> uri_encode(k) <> "=" <> uri_encode(v) end)
    |> Enum.sort()
    |> Enum.join("&")
  end
end
